local theme = {
    Background = Color3.fromRGB(17,17,17), Top = Color3.fromRGB(34,34,34),
    Sidebar = Color3.fromRGB(27,27,27), Panel = Color3.fromRGB(31,31,31),
    Input = Color3.fromRGB(22,22,22), Hover = Color3.fromRGB(45,42,44),
    Border = Color3.fromRGB(43,43,44), Black = Color3.fromRGB(12,12,12),
    Text = Color3.fromRGB(218,218,218), Muted = Color3.fromRGB(121,121,124),
    Dim = Color3.fromRGB(85,85,87), Accent = Color3.fromRGB(195,149,167),
    AccentBright = Color3.fromRGB(229,185,203), Green = Color3.fromRGB(147,184,173),
}
local function rgb(r: number, g: number, b: number): Color3 return Color3.fromRGB(r,g,b) end
local regular = Font.new("rbxasset://fonts/families/Montserrat.json",Enum.FontWeight.Medium,Enum.FontStyle.Normal)
local semi = Font.new("rbxasset://fonts/families/Montserrat.json",Enum.FontWeight.SemiBold,Enum.FontStyle.Normal)
local bold = Font.new("rbxasset://fonts/families/Montserrat.json",Enum.FontWeight.Bold,Enum.FontStyle.Normal)
local function new(class,parent,properties)
    local item=Instance.new(class)
    for key,value in properties or {} do item[key]=value end
    item.Parent=parent
    return item
end
local function rect(parent,x,y,w,h,col,z,class)
    return new(class or "Frame",parent,{Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),
        BackgroundColor3=col or theme.Panel,BorderSizePixel=0,ZIndex=z or 1})
end
local function round(obj,r) new("UICorner",obj,{CornerRadius=UDim.new(0,r or 4)}) return obj end
local function border(obj,color,size)
    return new("UIStroke",obj,{ApplyStrokeMode=Enum.ApplyStrokeMode.Border,Color=color or theme.Border,Thickness=size or 1})
end
local function label(parent,stringvalue,x,y,w,h,sz,col,isbold,align,z)
    return new("TextLabel",parent,{BackgroundTransparency=1,Position=UDim2.fromOffset(x,y),
        Size=UDim2.fromOffset(w,h),Text=tostring(stringvalue or ""),TextSize=sz or 11,
        FontFace=isbold and bold or regular,TextColor3=col or theme.Text,TextXAlignment=align or Enum.TextXAlignment.Left,
        TextYAlignment=Enum.TextYAlignment.Center,TextTruncate=Enum.TextTruncate.AtEnd,ZIndex=z or 7})
end
local function hit(parent,text,x,y,w,h,color,z)
    return new("TextButton",parent,{Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),
        Text=tostring(text or ""),TextSize=11,TextColor3=theme.Text,FontFace=semi,
        BackgroundColor3=color or theme.Input,BorderSizePixel=0,AutoButtonColor=false,ZIndex=z or 8})
end
local function separator(parent,x,y,w,col,z)
    return rect(parent,x,y,w,1,col or theme.Border,z or 6)
end
local function invoke(callback,...)
    if type(callback)=="function" then
        local ok,err=pcall(callback,...)
        if not ok then warn("[PrimordialUI] Callback error:",err) end
    end
end
local function hex(col: Color3): string
    return string.format("#%02X%02X%02X",math.floor(col.R*255+.5),math.floor(col.G*255+.5),math.floor(col.B*255+.5))
end
local function fromhex(v: any): Color3?
    if typeof(v)=="Color3" then return v end
    if type(v)~="string" then return nil end
    v=v:gsub("#", "")
    if #v~=6 or not v:match("^%x+$") then return nil end
    return Color3.fromRGB(tonumber(v:sub(1,2),16),tonumber(v:sub(3,4),16),tonumber(v:sub(5,6),16))
end
local function keyfrom(v)
    if typeof(v)=="EnumItem" then return v end
    if type(v)~="string" or v=="None" then return Enum.KeyCode.Unknown end
    return Enum.KeyCode[v] or Enum.KeyCode.Unknown
end
local function keytext(v)
    if not v or v==Enum.KeyCode.Unknown then return "None" end
    return v.Name
end
local function deepcopy(value)
    if type(value)~="table" then return value end
    local result={}
    for key,val in value do result[key]=deepcopy(val) end
    return result
end

local library = {Theme=theme,Options={},Toggles={},Connections={},Windows={},Animations=true,
    AccentBindings={},CleanupCallbacks={},UIBaseScale=1,Version="4.0.0",ConfigFolder="PrimordialUI/configs"}
local screen=new("ScreenGui",gethui(),{Name="PrimordialUI_Executor",ResetOnSpawn=false,IgnoreGuiInset=true,
    ZIndexBehavior=Enum.ZIndexBehavior.Sibling,DisplayOrder=100000})
library.ScreenGui=screen
environment.PrimordialUI=library

local function track(connection)
    table.insert(library.Connections,connection)
    return connection
end
local runningtweens=setmetatable({},{__mode="k"})
local tweentargets=setmetatable({},{__mode="k"})
local function smooth(object,props,duration)
    if not object or not object.Parent then return end
    local same=true
    local last=tweentargets[object]
    if not last then same=false else
        for key,value in props do
            if last[key]~=value then same=false break end
        end
    end
    if same and runningtweens[object] and library.Animations and duration and duration>0 then return end
    local previous=runningtweens[object]
    if previous then
        pcall(function() previous:Cancel() end)
        runningtweens[object]=nil
    end
    tweentargets[object]=props
    if not library.Animations or not duration or duration<=0 then
        for key,value in props do object[key]=value end
        return
    end
    local unchanged=true
    for key,value in props do
        if object[key]~=value then unchanged=false break end
    end
    if unchanged then return end
    local tween=tweenservice:Create(object,TweenInfo.new(duration,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),props)
    runningtweens[object]=tween
    tween:Play()
end
local function hover(buttonobj,normal,over)
    buttonobj.MouseEnter:Connect(function() smooth(buttonobj,{BackgroundColor3=over or theme.Hover},.12) end)
    buttonobj.MouseLeave:Connect(function() smooth(buttonobj,{BackgroundColor3=normal or theme.Input},.16) end)
end
local function accentobject(object,property,variant)
    table.insert(library.AccentBindings,{Object=object,Property=property,Variant=variant or "Accent"})
    object[property]=theme[variant or "Accent"]
    return object
end
function library:setaccent(value)
    local color=fromhex(value)
    if not color then return false end
    theme.Accent=color
    theme.AccentBright=color:Lerp(Color3.new(1,1,1),.24)
    for i=#self.AccentBindings,1,-1 do
        local item=self.AccentBindings[i]
        if item.Object and item.Object.Parent then
            item.Object[item.Property]=theme[item.Variant]
        else table.remove(self.AccentBindings,i) end
    end
    for unused,option in self.Toggles do
        if option.Value and option.Square and option.Square.Parent then
            option.Square.BackgroundColor3=theme.Accent
        end
    end
    for unused,win in self.Windows do
        for unused,tab in win.Tabs do
            for unused,page in tab.Pages do
                for unused,sub in page.Tabs do
                    sub.Button.TextColor3=page.ActiveSubTab==sub and theme.AccentBright or theme.Muted
                end
            end
        end
    end
    return true
end
function library:setanimations(enabled) self.Animations=not not enabled end
function library:setuiscale(scale)
    self.UIBaseScale=math.clamp(tonumber(scale) or 1,.7,1.3)
    for unused,win in self.Windows do if win.relayout then win:relayout() end end
end
function library:destroy()
    if self.Destroyed then return end
    self.Destroyed=true
    for unused,win in self.Windows do if win.Popup then win.Popup:destroy() end end
    for unused,callback in self.CleanupCallbacks do pcall(callback) end
    for unused,conn in self.Connections do pcall(function() conn:Disconnect() end) end
    for object,tween in runningtweens do
        pcall(function() tween:Cancel() end)
        runningtweens[object]=nil
    end
    if screen then screen:Destroy() end
    if environment.PrimordialUI==self then environment.PrimordialUI=nil end
end
local function remember(id,obj,kind,options)
    if id~=nil then
        obj.Id=tostring(id)
        obj.Kind=kind
        obj.NoSave=options and options.NoSave
        library.Options[obj.Id]=obj
        if kind=="Toggle" then library.Toggles[obj.Id]=obj end
    end
    return obj
end

local embeddedimages = {
    logo = [==[]==],
    rage = [==[]==],
    legit = [==[]==],
    visuals = [==[]==],
    misc = [==[]==],
    skins = [==[]==],
    scripts = [==[]==],
}
local function decode(data: string): string
    if type(crypt)=="table" and type(crypt.base64decode)=="function" then
        local ok,result=pcall(crypt.base64decode,data)
        if ok and type(result)=="string" and result:sub(1,8)=="\137PNG\r\n\26\n" then return result end
    end
    local chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map={}
    for i=1,#chars do map[chars:byte(i)]=i-1 end
    local out={}
    for i=1,#data,4 do
        local a,b,c,d=data:byte(i,i+3)
        if a and b then
            local n=(map[a] or 0)*262144+(map[b] or 0)*4096+(map[c] or 0)*64+(map[d] or 0)
            out[#out+1]=string.char(math.floor(n/65536)%256)
            if c and c~=61 then out[#out+1]=string.char(math.floor(n/256)%256) end
            if d and d~=61 then out[#out+1]=string.char(n%256) end
        end
    end
    return table.concat(out)
end
local function folder(path: string): boolean
    if type(makefolder)~="function" then return false end
    local current=""
    for part in string.gmatch(path,"[^/]+") do
        current=(current=="") and part or (current.."/"..part)
        local exists=false
        if type(isfolder)=="function" then local ok,result=pcall(isfolder,current);exists=ok and result end
        if not exists then pcall(makefolder,current) end
    end
    return true
end
local images={}
if type(writefile)=="function" and type(getcustomasset)=="function" then
    folder("PrimordialUI/assets")
    for name,data in embeddedimages do
        local path="PrimordialUI/assets/"..name.."-v4.png"
        local exists=false
        if type(isfile)=="function" then local ok,result=pcall(isfile,path);exists=ok and result end
        if exists and type(readfile)=="function" then
            local ok,result=pcall(readfile,path)
            exists=ok and type(result)=="string" and #result>64 and result:sub(1,8)=="\137PNG\r\n\26\n"
        end
        if not exists then pcall(writefile,path,decode(data)) end
        local ok,id=pcall(getcustomasset,path)
        if ok and type(id)=="string" then images[name]=id end
    end
end
embeddedimages=nil
library.Images=images

