local function viewport(): Vector2
    local camera=workspace.CurrentCamera
    return camera and camera.ViewportSize or Vector2.new(1280,720)
end
local function killpopup(win)
    if win and win.Popup then win.Popup:destroy() end
end
local function overlay(win,anchor,width,height,closeonoutside)
    killpopup(win)
    local shade=hit(screen,"",0,0,0,0,theme.Background,101)
    shade.Size=UDim2.fromScale(1,1)
    shade.BackgroundTransparency=1
    local pop=rect(screen,0,0,width,height,theme.Panel,102,"Frame")
    round(pop,5);border(pop,theme.Black)
    pop.BackgroundTransparency=1
    local scale=win.Scale.Scale
    local popscale=new("UIScale",pop,{Scale=scale})
    local v=viewport()
    local abs=anchor.AbsolutePosition
    local bottom=abs.Y+anchor.AbsoluteSize.Y+4
    local x=math.clamp(abs.X,6,math.max(6,v.X-width*scale-6))
    local y=(bottom+height*scale>v.Y-7) and (abs.Y-height*scale-4) or bottom
    y=math.clamp(y,6,math.max(6,v.Y-height*scale-6))
    pop.Position=UDim2.fromOffset(x,y)
    local data={Frame=pop,Shade=shade,Scale=popscale}
    function data:destroy()
        if self.Destroyed then return end
        self.Destroyed=true
        if win.Popup==self then win.Popup=nil end
        if self.OnClose then invoke(self.OnClose) end
        if shade.Parent then shade:Destroy() end
        if not pop.Parent then return end
        if not library.Animations then pop:Destroy();return end
        smooth(pop,{BackgroundTransparency=1},.13)
        task.delay(.15,function() if pop.Parent then pop:Destroy() end end)
    end
    if closeonoutside~=false then
        shade.MouseButton1Click:Connect(function() data:destroy() end)
    end
    win.Popup=data
    smooth(pop,{BackgroundTransparency=0},.16)
    return pop,data
end

local function row(group,height)
    group.Count+=1
    local r=rect(group.Inner,0,0,0,height,theme.Panel,6)
    r.BackgroundTransparency=1
    r.Size=UDim2.new(1,0,0,height)
    r.LayoutOrder=group.Count
    group.HeightSum+=height
    group:refreshheight()
    return r
end
function groupclass:refreshheight()
    local needed=42+self.HeightSum+math.max(self.Count-1,0)*4+6
    self.Container.Size=UDim2.new(1,-2,0,math.max(self.MinHeight,needed))
end
function groupclass:addlabel(value)
    local r=row(self,21)
    local text=type(value)=="table" and value.Text or value
    local l=label(r,text,0,0,0,21,11,theme.Text)
    l.Size=UDim2.new(1,0,1,0)
    return l
end
function groupclass:adddivider()
    local r=row(self,10)
    local ln=separator(r,0,5,0,theme.Border)
    ln.Size=UDim2.new(1,0,0,1)
    return ln
end

function groupclass:addtoggle(opts)
    local o=type(opts)=="string" and {Text=opts} or (opts or {})
    local r=row(self,24)
    local square=hit(r,"",0,4,16,16,theme.Input,9)
    round(square,4);border(square,theme.Border)
    local check=rect(square,2,3,12,10,theme.Input,10)
    check.BackgroundTransparency=1
    local tickleft=rect(check,1,5,5,2,theme.Black,11)
    tickleft.Rotation=45
    local tickright=rect(check,4,3,9,2,theme.Black,11)
    tickright.Rotation=-45
    local caption=label(r,o.Text or "Toggle",23,0,0,24,11,theme.Text,true)
    caption.Size=UDim2.new(1,-27,0,24)
    local click=hit(r,"",22,0,0,24,theme.Panel,8)
    click.BackgroundTransparency=1
    click.Size=UDim2.new(1,-27,0,24)
    local attached=new("ScrollingFrame",r,{Position=UDim2.new(1,0,0,0),Size=UDim2.fromOffset(0,24),
        BackgroundTransparency=1,BorderSizePixel=0,ZIndex=9,ScrollingDirection=Enum.ScrollingDirection.X,
        CanvasSize=UDim2.fromOffset(0,24),ScrollBarThickness=2,ScrollBarImageColor3=theme.Accent,
        ClipsDescendants=true})
    accentobject(attached,"ScrollBarImageColor3")
    new("UIListLayout",attached,{FillDirection=Enum.FillDirection.Horizontal,SortOrder=Enum.SortOrder.LayoutOrder,
        HorizontalAlignment=Enum.HorizontalAlignment.Left,VerticalAlignment=Enum.VerticalAlignment.Center,
        Padding=UDim.new(0,5)})
    local group=self
    local ctrl={Value=not not o.Default,Attachments=attached,AttachmentWidth=0,Row=r,Caption=caption,Square=square}
    table.insert(self.ResponsiveControls,ctrl)
    function ctrl:refresh()
        smooth(square,{BackgroundColor3=self.Value and theme.Accent or theme.Input},.12)
        check.Visible=self.Value
        caption.TextColor3=self.Value and theme.Text or theme.Muted
    end
    function ctrl:setvalue(value,silent)
        local nextvalue=not not value
        local changed=self.Value~=nextvalue
        self.Value=nextvalue
        self:refresh()
        if not silent and changed then invoke(o.Callback,self.Value) end
    end
    function ctrl:getvalue() return self.Value end
    function ctrl:relayout()
        local available=group.Window.Stacked and math.min(190,math.max(115,group.Window.Width-150)) or 190
        local width=math.min(self.AttachmentWidth,available)
        attached.Size=UDim2.fromOffset(width,24)
        attached.Position=UDim2.new(1,-width,0,0)
        attached.CanvasSize=UDim2.fromOffset(self.AttachmentWidth,24)
        caption.Size=UDim2.new(1,-(27+width+4),0,24)
        click.Size=UDim2.new(1,-(27+width+4),0,24)
    end
    function ctrl:addattached(width)
        self.AttachmentWidth+=width+(self.AttachmentWidth>0 and 5 or 0)
        self:relayout()
    end
    function ctrl:addcolorpicker(options)
        local cpoptions=options or {}
        self:addattached(20)
        local wrapper=rect(attached,0,0,20,22,theme.Panel,9)
        wrapper.BackgroundTransparency=1
        wrapper.LayoutOrder=self.AttachmentWidth
        return groupclass.colorpicker(cpoptions,wrapper,true,group)
    end
    function ctrl:addkeypicker(options)
        self:addattached(91)
        local wrapper=rect(attached,0,0,91,22,theme.Panel,9)
        wrapper.BackgroundTransparency=1
        wrapper.LayoutOrder=self.AttachmentWidth
        return groupclass.keypicker(options,wrapper,true,ctrl,group)
    end
    local function emphasize()
        smooth(square,{BackgroundColor3=ctrl.Value and theme.AccentBright or theme.Hover},.12)
    end
    square.MouseEnter:Connect(emphasize)
    click.MouseEnter:Connect(emphasize)
    square.MouseLeave:Connect(function() ctrl:refresh() end)
    click.MouseLeave:Connect(function() ctrl:refresh() end)
    square.MouseButton1Click:Connect(function() ctrl:setvalue(not ctrl.Value) end)
    click.MouseButton1Click:Connect(function() ctrl:setvalue(not ctrl.Value) end)
    ctrl:setvalue(ctrl.Value,true)
    ctrl:relayout()
    return remember(o.Id,ctrl,"Toggle",o)
end

track(inputservice.InputChanged:Connect(function(input)
    local active=library.SliderDrag
    if not active then return end
    local touch=active.Input.UserInputType==Enum.UserInputType.Touch
    if (touch and input==active.Input) or (not touch and input.UserInputType==Enum.UserInputType.MouseMovement) then
        active.Update(input.Position.X)
    end
end))
track(inputservice.InputEnded:Connect(function(input)
    local active=library.SliderDrag
    if active and (input==active.Input or
        (active.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then
        library.SliderDrag=nil
    end
end))
local function sliderpointer(r,trackbar,callback)
    local function setpos(x)
        local a=(x-trackbar.AbsolutePosition.X)/math.max(1,trackbar.AbsoluteSize.X)
        callback(math.clamp(a,0,1))
    end
    local grab=hit(r,"",0,21,0,18,theme.Input,11)
    grab.Size=UDim2.new(1,0,0,18)
    grab.BackgroundTransparency=1
    grab.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            library.SliderDrag={Input=input,Update=setpos}
            setpos(input.Position.X)
        end
    end)
    return grab
end
function groupclass:addslider(o)
    o=o or {}
    local r=row(self,40)
    local min,max=tonumber(o.Min) or 0,tonumber(o.Max) or 100
    if max<=min then max=min+1 end
    local decimals=math.clamp(tonumber(o.Decimals or o.Rounding) or 0,0,5)
    local step=10^(-decimals)
    local caption=label(r,o.Text or "Slider",0,0,0,18,11,theme.Text,true)
    caption.Size=UDim2.new(1,-90,0,18)
    local readout=label(r,"",0,0,85,18,11,theme.Muted,true,Enum.TextXAlignment.Right)
    readout.Position=UDim2.new(1,-85,0,0)
    local bar=rect(r,0,25,0,9,theme.Input,8)
    bar.Size=UDim2.new(1,0,0,9)
    round(bar,4);border(bar,theme.Border)
    local fill=rect(bar,0,0,0,9,theme.Accent,9)
    fill.Size=UDim2.new(0,0,1,0)
    round(fill,4);accentobject(fill,"BackgroundColor3")
    local knob=rect(bar,0,-2,5,13,rgb(181,181,181),10)
    round(knob,2)
    local ctrl={Value=min,Row=r}
    local function format(v)
        if type(o.Format)=="function" then return tostring(o.Format(v)) end
        return (o.Prefix or "")..string.format("%0."..decimals.."f",v)..(o.Suffix or "")
    end
    function ctrl:setvalue(v,silent)
        v=math.clamp(tonumber(v) or min,min,max)
        v=math.clamp(math.floor((v-min)/step+.5)*step+min,min,max)
        local changed=self.Value~=v
        self.Value=v
        local a=(v-min)/(max-min)
        fill.Size=UDim2.new(a,0,1,0)
        knob.Position=UDim2.new(a,-2,0,-2)
        readout.Text=format(v)
        if not silent and changed then invoke(o.Callback,v) end
    end
    function ctrl:getvalue() return self.Value end
    local grab=sliderpointer(r,bar,function(alpha) ctrl:setvalue(min+alpha*(max-min)) end)
    if grab then
        grab.MouseEnter:Connect(function() smooth(knob,{BackgroundColor3=theme.AccentBright},.13) end)
        grab.MouseLeave:Connect(function() smooth(knob,{BackgroundColor3=rgb(181,181,181)},.13) end)
    end
    ctrl:setvalue(o.Default or min,true)
    return remember(o.Id,ctrl,"Slider",o)
end

local function optionspopup(win,ctrl,anchor,items,multi)
    local windowscale=math.max(.01,win.Scale.Scale)
    local width=math.max(160,math.floor(anchor.AbsoluteSize.X/windowscale+.5))
    local footer=multi and 34 or 0
    local visiblecount=math.min(math.max(#items,1),8)
    local maxheight=math.max(86,math.floor(viewport().Y/windowscale-18))
    local height=math.min(visiblecount*27+8+footer,maxheight)
    local popup,record=overlay(win,anchor,width,height)
    local scrollheight=height-footer-8
    local scroll=new("ScrollingFrame",popup,{BackgroundTransparency=1,BorderSizePixel=0,
        Position=UDim2.fromOffset(4,4),Size=UDim2.new(1,-8,0,scrollheight),
        CanvasSize=UDim2.fromOffset(0,#items*27),ScrollingDirection=Enum.ScrollingDirection.Y,
        ScrollBarThickness=3,ScrollBarImageColor3=theme.Accent,ClipsDescendants=true,ZIndex=104})
    accentobject(scroll,"ScrollBarImageColor3")
    local rows={}
    local hovered=nil
    local function selected(value)
        if multi then return ctrl.Value[value]==true end
        return tostring(ctrl.Value)==value or
            (typeof(ctrl.Value)=="EnumItem" and ctrl.Value.Name==value)
    end
    local function paint(index,animate)
        local entry=rows[index]
        if not entry or not entry.Button.Parent then return end
        local isselected=selected(entry.Value)
        local over=hovered==index
        local color=(isselected and theme.Accent:Lerp(theme.Input,.82)) or (over and theme.Hover or theme.Input)
        local textcolor=isselected and theme.AccentBright or (over and theme.Text or theme.Muted)
        smooth(entry.Button,{BackgroundColor3=color,TextColor3=textcolor},animate and .075 or 0)
        if entry.Mark then
            entry.Mark.BackgroundColor3=isselected and theme.Accent or theme.Border
            entry.MarkFill.Visible=isselected
        end
    end
    local function sethovered(index)
        if hovered==index then return end
        local old=hovered
        hovered=index
        if old then paint(old,true) end
        if index then paint(index,true) end
    end
    for idx,item in items do
        local value=tostring(item)
        local opt=hit(scroll,value,0,(idx-1)*27,0,26,theme.Input,105)
        opt.Size=UDim2.new(1,-5,0,26)
        opt.TextXAlignment=Enum.TextXAlignment.Left
        opt.TextColor3=theme.Muted
        new("UIPadding",opt,{PaddingLeft=UDim.new(0,8),PaddingRight=UDim.new(0,multi and 24 or 5)})
        local mark,markfill=nil,nil
        if multi then
            mark=rect(opt,0,6,14,14,theme.Border,106)
            mark.Position=UDim2.new(1,-21,0,6)
            round(mark,3)
            markfill=rect(mark,3,3,8,8,theme.Black,107)
            round(markfill,2)
        end
        rows[idx]={Button=opt,Value=value,Mark=mark,MarkFill=markfill}
        paint(idx,false)
        opt.MouseButton1Click:Connect(function()
            if record.Destroyed then return end
            if multi then
                local copy=deepcopy(ctrl.Value)
                copy[value]=not copy[value]
                ctrl:setvalue(copy)
                paint(idx,false)
            else
                ctrl:setvalue(value)
                record:destroy()
            end
        end)
        opt.MouseEnter:Connect(function() if not record.Destroyed then sethovered(idx) end end)
        opt.MouseLeave:Connect(function() if hovered==idx then sethovered(nil) end end)
    end
    if #items==0 then
        local empty=label(scroll,"No options available",8,0,0,26,11,theme.Muted,false,nil,105)
        empty.Size=UDim2.new(1,-12,0,26)
    end
    local mousemove=inputservice.InputChanged:Connect(function(input)
        if record.Destroyed or input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local pos=input.Position
        local origin=scroll.AbsolutePosition
        local size=scroll.AbsoluteSize
        if pos.X<origin.X or pos.Y<origin.Y or pos.X>origin.X+size.X or pos.Y>origin.Y+size.Y then
            sethovered(nil)
            return
        end
        local scrolly=scroll.CanvasPosition and scroll.CanvasPosition.Y or 0
        local index=math.floor((pos.Y-origin.Y+scrolly)/27)+1
        if index<1 or index>#items then index=nil end
        sethovered(index)
    end)
    popup.Destroying:Connect(function()
        mousemove:Disconnect()
        hovered=nil
    end)
    if multi then
        local bottom=rect(popup,4,height-footer,0,footer,theme.Panel,105)
        bottom.Size=UDim2.new(1,-8,0,footer)
        local done=hit(bottom,"Done",0,3,71,27,theme.Input,106)
        done.Position=UDim2.new(1,-71,0,3)
        round(done,4);border(done,theme.Border);hover(done)
        done.MouseButton1Click:Connect(function() record:destroy() end)
        local count=0
        for unused,item in items do if ctrl.Value[tostring(item)] then count+=1 end end
        local countlabel=label(bottom,tostring(count).." selected",3,3,0,27,10,theme.Muted,false,nil,106)
        countlabel.Size=UDim2.new(1,-80,0,27)
        for unused,entry in rows do
            entry.Button.MouseButton1Click:Connect(function()
                if record.Destroyed then return end
                local total=0
                for unused,choice in items do if ctrl.Value[tostring(choice)] then total+=1 end end
                countlabel.Text=tostring(total).." selected"
            end)
        end
    end
    return record
end
function groupclass:adddropdown(o)
    o=o or {}
    local r=row(self,49)
    local caption=label(r,o.Text or "Dropdown",0,0,0,18,11,theme.Text,true)
    caption.Size=UDim2.new(1,0,0,18)
    local buttonobj=hit(r,"",0,20,0,26,theme.Input,8)
    buttonobj.Size=UDim2.new(1,0,0,26)
    round(buttonobj,4);border(buttonobj,theme.Border)
    hover(buttonobj)
    local display=label(buttonobj,"",8,0,0,26,11,theme.Muted,true)
    display.Size=UDim2.new(1,-38,1,0)
    local icon=rect(buttonobj,0,0,16,16,theme.Input,10)
    icon.BackgroundTransparency=1
    icon.Position=UDim2.new(1,-23,.5,-8)
    local plushorizontal=rect(icon,3,7,10,2,theme.Muted,11)
    round(plushorizontal,1)
    local plusvertical=rect(icon,7,3,2,10,theme.Muted,11)
    round(plusvertical,1)
    local choices=deepcopy(o.Values or o.Options or {})
    local ctrl={Value=o.Multi and {} or "",Values=choices,Multi=not not o.Multi,Popup=nil,
        Button=buttonobj,Display=display,Row=r,Plus=plusvertical}
    local function exists(value)
        for unused,item in choices do
            if tostring(item)==value then return true end
        end
        return false
    end
    local function textvalue()
        if not ctrl.Multi then return tostring(ctrl.Value) end
        local names={}
        for unused,choice in choices do
            if ctrl.Value[tostring(choice)] then names[#names+1]=tostring(choice) end
        end
        return #names>0 and table.concat(names,", ") or "None selected"
    end
    function ctrl:setvalue(value,silent)
        local changed=false
        if self.Multi then
            local selected={}
            if type(value)=="table" then
                for key,item in value do
                    local v
                    if type(key)=="number" then
                        if type(item)=="number" then v=choices[item] else v=item end
                    elseif item then v=key end
                    if v and exists(tostring(v)) then selected[tostring(v)]=true end
                end
            elseif type(value)=="number" and choices[value] then
                selected[tostring(choices[value])]=true
            elseif value~=nil and exists(tostring(value)) then
                selected[tostring(value)]=true
            end
            for key in selected do if not self.Value[key] then changed=true break end end
            if not changed then
                for key in self.Value do if not selected[key] then changed=true break end end
            end
            self.Value=selected
        else
            local nextvalue
            if type(value)=="number" and choices[value]~=nil then
                nextvalue=tostring(choices[value])
            else
                nextvalue=tostring(value or "")
            end
            changed=self.Value~=nextvalue
            self.Value=nextvalue
        end
        display.Text=textvalue()
        if not silent and changed then invoke(o.Callback,deepcopy(self.Value)) end
    end
    function ctrl:getvalue() return deepcopy(self.Value) end
    function ctrl:setvalues(values)
        choices=deepcopy(values or {})
        self.Values=choices
        if self.Popup and not self.Popup.Destroyed then self.Popup:destroy() end
        if self.Multi then
            self:setvalue(self.Value,true)
        else
            if not exists(tostring(self.Value)) then
                self:setvalue(choices[1] or "None selected",true)
            else display.Text=textvalue() end
        end
    end
    buttonobj.MouseButton1Click:Connect(function()
        if ctrl.Popup and not ctrl.Popup.Destroyed then
            ctrl.Popup:destroy()
            return
        end
        plusvertical.Visible=false
        local record=optionspopup(self.Window,ctrl,buttonobj,choices,ctrl.Multi)
        ctrl.Popup=record
        record.OnClose=function()
            if ctrl.Popup==record then ctrl.Popup=nil end
            plusvertical.Visible=true
        end
    end)
    ctrl:setvalue(o.Default~=nil and o.Default or (ctrl.Multi and {} or choices[1] or "None selected"),true)
    return remember(o.Id,ctrl,ctrl.Multi and "MultiDropdown" or "Dropdown",o)
end
function groupclass:addmultidropdown(o)
    o=o or {};o.Multi=true
    return self:adddropdown(o)
end

local activekeybinds={}
track(inputservice.InputBegan:Connect(function(input,processed)
    local capture=library.KeyCapture
    if capture and capture.Listening then
        if input.UserInputType==Enum.UserInputType.Keyboard then
            local value=input.KeyCode==Enum.KeyCode.Escape and Enum.KeyCode.Unknown or input.KeyCode
            library.KeyCapture=nil
            capture:setvalue(value)
        end
        return
    end
    if processed or inputservice:GetFocusedTextBox() then return end
    if input.UserInputType~=Enum.UserInputType.Keyboard then return end
    for unused,bind in activekeybinds do
        if bind.Value~=Enum.KeyCode.Unknown and bind.Value==input.KeyCode then
            if bind.Toggle then
                if bind.Mode=="Hold" then bind.Toggle:setvalue(true)
                elseif bind.Mode=="Toggle" then bind.Toggle:setvalue(not bind.Toggle.Value)
                elseif bind.Mode=="Always" then bind.Toggle:setvalue(true) end
            end
            invoke(bind.KeyCallback,true)
        end
    end
end))
track(inputservice.InputEnded:Connect(function(input)
    if input.UserInputType~=Enum.UserInputType.Keyboard then return end
    for unused,bind in activekeybinds do
        if bind.Value~=Enum.KeyCode.Unknown and bind.Value==input.KeyCode then
            if bind.Toggle and bind.Mode=="Hold" then bind.Toggle:setvalue(false) end
            invoke(bind.KeyCallback,false)
        end
    end
end))
function groupclass.keypicker(o,parent,attached,toggle,group)
    o=o or {}
    local win=group and group.Window or library.CurrentWindow
    local width=attached and 91 or 121
    local btn=hit(parent,"",0,attached and 0 or 1,width,attached and 22 or 25,theme.Input,9)
    if attached then btn.Size=UDim2.new(1,0,1,0) end
    round(btn,4);border(btn,theme.Border)
    hover(btn)
    local ctrl={Value=keyfrom(o.Default or "None"),Mode=o.Mode or "Toggle",Listening=false}
    function ctrl:refresh()
        btn.Text=self.Listening and "Press key..." or ("Key: "..keytext(self.Value))
    end
    function ctrl:setvalue(v,silent)
        if type(v)=="table" and typeof(v)~="EnumItem" then
            if v.Mode then self:setmode(v.Mode) end
            v=v.Key or v.Value or "None"
        end
        self.Value=keyfrom(v)
        self.Listening=false
        self:refresh()
        if not silent then invoke(o.Changed,self.Value) end
    end
    function ctrl:getvalue() return self.Value end
    function ctrl:setmode(v)
        if v=="Hold" or v=="Toggle" or v=="Always" then
            self.Mode=v
            if self.Toggle and v=="Always" then self.Toggle:setvalue(true) end
        end
    end
    local function keymenu()
        local keys={"None","RightShift","LeftAlt","LeftControl","E","F","Q","R","T","G","X","Z","C","V","F1","F2","F3","MouseButton1"}
        local options={}
        for unused,v in keys do if v~="MouseButton1" then table.insert(options,v) end end
        optionspopup(win,ctrl,btn,options,false)
    end
    btn.MouseButton1Click:Connect(function()
        if inputservice.TouchEnabled and not inputservice.KeyboardEnabled then
            keymenu()
        else
            if library.KeyCapture and library.KeyCapture~=ctrl then library.KeyCapture.Listening=false;library.KeyCapture:refresh() end
            library.KeyCapture=ctrl
            ctrl.Listening=true
            ctrl:refresh()
        end
    end)
    btn.MouseButton2Click:Connect(function()
        local nextmode={Hold="Toggle",Toggle="Always",Always="Hold"}
        ctrl:setmode(nextmode[ctrl.Mode] or "Toggle")
        library:notify("Bind mode: "..ctrl.Mode,1.4)
    end)
    ctrl.Toggle=toggle
    ctrl.KeyCallback=o.Callback
    table.insert(activekeybinds,ctrl)
    ctrl:setvalue(ctrl.Value,true)
    return remember(o.Id,ctrl,"KeyPicker",o)
end
