function groupclass.colorpicker(o,parent,attached,group)
    o=o or {}
    local win=group and group.Window or library.CurrentWindow
    assert(win and win.Scale and win.Scale.Scale, "Color picker requires a valid window")
    local initial=fromhex(o.Default) or theme.Accent
    local box=hit(parent,"",0,attached and 3 or 2,attached and 20 or 27,attached and 16 or 19,initial,9)
    if attached then box.Position=UDim2.fromOffset(0,3) end
    round(box,3)
    border(box,theme.Black)
    local ctrl={Value=initial,ActivePopup=nil}
    function ctrl:setvalue(value,silent)
        local color=fromhex(value)
        if not color then return false end
        local prior=self.Value
        self.Value=color
        box.BackgroundColor3=color
        if self.PopupRefresh and not self.UpdatingFromPopup then
            self.PopupRefresh(color)
        end
        if not silent and (not prior or math.abs(prior.R-color.R)+math.abs(prior.G-color.G)+math.abs(prior.B-color.B)>0.000001) then
            invoke(o.Callback,color)
        end
        return true
    end
    function ctrl:getvalue() return self.Value end
    box.MouseEnter:Connect(function()
        if not ctrl.ActivePopup then smooth(box,{BackgroundColor3=ctrl.Value:Lerp(Color3.new(1,1,1),.2)},.12) end
    end)
    box.MouseLeave:Connect(function()
        if not ctrl.ActivePopup then smooth(box,{BackgroundColor3=ctrl.Value},.12) end
    end)
    box.MouseButton1Click:Connect(function()
        if ctrl.ActivePopup and not ctrl.ActivePopup.Destroyed then return end
        smooth(box,{BackgroundColor3=ctrl.Value},.1)
        local pop,record=overlay(win,box,255,212,false)
        ctrl.ActivePopup=record
        label(pop,o.Text or "Color picker",10,5,235,22,12,theme.Text,true,nil,106)
        local h,s,v=ctrl.Value:ToHSV()
        local area=rect(pop,10,32,174,132,Color3.fromHSV(h,1,1),105)
        area.Active=true
        round(area,3)
        local white=rect(area,0,0,174,132,Color3.new(1,1,1),106)
        white.Active=true
        white.Size=UDim2.fromScale(1,1)
        new("UIGradient",white,{Transparency=NumberSequence.new({
            NumberSequenceKeypoint.new(0,0),NumberSequenceKeypoint.new(1,1)}),Rotation=0})
        local black=rect(area,0,0,174,132,Color3.new(0,0,0),107)
        black.Active=true
        black.Size=UDim2.fromScale(1,1)
        new("UIGradient",black,{Transparency=NumberSequence.new({
            NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(1,0)}),Rotation=90})
        local circle=rect(area,0,0,9,9,theme.Text,109)
        round(circle,9)
        border(circle,theme.Black)
        local huebar=rect(pop,192,32,23,132,Color3.new(1,1,1),105)
        huebar.Active=true
        round(huebar,3)
        new("UIGradient",huebar,{Rotation=90,Color=ColorSequence.new({
            ColorSequenceKeypoint.new(0,Color3.fromHSV(0,1,1)),
            ColorSequenceKeypoint.new(1/6,Color3.fromHSV(1/6,1,1)),
            ColorSequenceKeypoint.new(2/6,Color3.fromHSV(2/6,1,1)),
            ColorSequenceKeypoint.new(3/6,Color3.fromHSV(3/6,1,1)),
            ColorSequenceKeypoint.new(4/6,Color3.fromHSV(4/6,1,1)),
            ColorSequenceKeypoint.new(5/6,Color3.fromHSV(5/6,1,1)),
            ColorSequenceKeypoint.new(1,Color3.fromHSV(1,1,1))})})
        local huehit=hit(huebar,"",0,0,0,0,Color3.new(1,1,1),110)
        huehit.Size=UDim2.fromScale(1,1)
        huehit.BackgroundTransparency=1
        local indicator=rect(huebar,-3,0,29,4,theme.Text,111)
        border(indicator,theme.Black)
        local preview=rect(pop,223,32,22,45,ctrl.Value,106)
        round(preview,3)
        border(preview,theme.Border)
        local hexinput=new("TextBox",pop,{Position=UDim2.fromOffset(10,175),Size=UDim2.fromOffset(174,27),
            Text=hex(ctrl.Value),TextColor3=theme.Text,TextSize=11,FontFace=regular,
            ClearTextOnFocus=false,BackgroundColor3=theme.Input,BorderSizePixel=0,ZIndex=108})
        round(hexinput,4)
        border(hexinput,theme.Border)
        local done=hit(pop,"OK",192,175,53,27,theme.Input,108)
        round(done,4)
        hover(done)
        local function redraw()
            area.BackgroundColor3=Color3.fromHSV(h,1,1)
            preview.BackgroundColor3=ctrl.Value
            hexinput.Text=hex(ctrl.Value)
            circle.Position=UDim2.new(s,-4,1-v,-4)
            indicator.Position=UDim2.new(0,-3,h,-2)
        end
        ctrl.PopupRefresh=function(color)
            if not pop.Parent or record.Destroyed then return end
            h,s,v=color:ToHSV()
            redraw()
        end
        local function applycolor()
            ctrl.UpdatingFromPopup=true
            ctrl:setvalue(Color3.fromHSV(h,s,v))
            ctrl.UpdatingFromPopup=false
            redraw()
        end
        local dragging=nil
        local function updatearea(pos)
            s=math.clamp((pos.X-area.AbsolutePosition.X)/math.max(1,area.AbsoluteSize.X),0,1)
            v=1-math.clamp((pos.Y-area.AbsolutePosition.Y)/math.max(1,area.AbsoluteSize.Y),0,1)
            applycolor()
        end
        local function updatehue(pos)
            h=math.clamp((pos.Y-huebar.AbsolutePosition.Y)/math.max(1,huebar.AbsoluteSize.Y),0,1)
            applycolor()
        end
        local function begindrag(input,kind)
            if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
                dragging={Input=input,Type=kind}
                if kind=="SV" then updatearea(input.Position) else updatehue(input.Position) end
            end
        end
        for unused,item in {area,white,black} do
            item.InputBegan:Connect(function(input) begindrag(input,"SV") end)
        end
        huehit.InputBegan:Connect(function(input) begindrag(input,"Hue") end)
        huebar.InputBegan:Connect(function(input) begindrag(input,"Hue") end)
        local change=inputservice.InputChanged:Connect(function(input)
            if not dragging or record.Destroyed then return end
            local initiating=dragging.Input
            if (initiating.UserInputType==Enum.UserInputType.Touch and input==initiating) or
                (initiating.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement) then
                if dragging.Type=="SV" then updatearea(input.Position) else updatehue(input.Position) end
            end
        end)
        local finish=inputservice.InputEnded:Connect(function(input)
            if dragging and (dragging.Input==input or
                (dragging.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then
                dragging=nil
            end
        end)
        pop.Destroying:Connect(function()
            change:Disconnect()
            finish:Disconnect()
            if ctrl.ActivePopup==record then ctrl.ActivePopup=nil end
            ctrl.PopupRefresh=nil
            ctrl.UpdatingFromPopup=false
        end)
        hexinput.FocusLost:Connect(function()
            local value=fromhex(hexinput.Text)
            if value then
                h,s,v=value:ToHSV()
                applycolor()
            else
                redraw()
            end
        end)
        done.MouseButton1Click:Connect(function() record:destroy() end)
        redraw()
    end)
    return remember(o.Id,ctrl,"ColorPicker",o)
end
