function library:createwindow(options)
    local o=options or {}
    local win=setmetatable({Tabs={},ActiveTab=nil,Popup=nil,Visible=true,Mobile=false,
        ToggleKey=keyfrom(o.ToggleKey or "RightShift"),Width=834,Height=586},windowclass)
