    new("UIListLayout",tabstrip,{FillDirection=Enum.FillDirection.Horizontal,
        HorizontalAlignment=Enum.HorizontalAlignment.Center,SortOrder=Enum.SortOrder.LayoutOrder,
        Padding=UDim.new(0,1)})
    win.Top=top;win.Side=side;win.Sidebar=sidelist;win.SideDivider=divide
    win.Stage=stage;win.Bottom=bottom;win.TabStrip=tabstrip
    win.TopEdge=topedge;win.BottomEdge=bottomedge;win.HideButton=hide
    local veil=rect(root,0,0,834,586,theme.Background,80)
    veil.Size=UDim2.fromScale(1,1)
    veil.BackgroundTransparency=1
    veil.Visible=false

    local reopen=hit(screen,"",0,0,42,42,theme.Top,95)
    reopen.AnchorPoint=Vector2.new(1,0)
    reopen.Position=UDim2.new(1,-10,0,12)
    round(reopen,9);border(reopen,theme.Accent)
    accentobject(reopen:FindFirstChildOfClass("UIStroke"),"Color")
    if images.legit then
        new("ImageLabel",reopen,{BackgroundTransparency=1,Image=images.legit,ImageColor3=theme.AccentBright,
            Position=UDim2.fromOffset(9,9),Size=UDim2.fromOffset(24,24),ZIndex=96})
    else
        reopen.Text="P";reopen.TextColor3=theme.AccentBright;reopen.TextSize=19
    end
    reopen.Visible=false
    win.Reopen=reopen
    reopen.MouseButton1Click:Connect(function() win:setvisible(true) end)
    hide.MouseButton1Click:Connect(function() win:setvisible(false) end)

    local activedrag=nil
    top.Active=true
    top.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            activedrag={Input=input,Start=input.Position,
                Center=root.AbsolutePosition+root.AbsoluteSize/2}
        end
    end)
    track(inputservice.InputChanged:Connect(function(input)
        if not activedrag then return end
        local istouch=activedrag.Input.UserInputType==Enum.UserInputType.Touch
        if (istouch and input~=activedrag.Input) or (not istouch and input.UserInputType~=Enum.UserInputType.MouseMovement) then return end
        local delta=Vector2.new(input.Position.X-activedrag.Start.X,input.Position.Y-activedrag.Start.Y)
        local v=viewport()
        local actual=root.AbsoluteSize
        local half=actual/2
        local destination=activedrag.Center+delta
        local left=math.min(v.X/2,half.X+5)
        local right=math.max(v.X/2,v.X-half.X-5)
        local topbound=math.min(v.Y/2,half.Y+5)
        local bottombound=math.max(v.Y/2,v.Y-half.Y-5)
        win.Dragged=true
        root.Position=UDim2.fromOffset(math.clamp(destination.X,left,right),math.clamp(destination.Y,topbound,bottombound))
    end))
    track(inputservice.InputEnded:Connect(function(input)
        if activedrag and (input==activedrag.Input or
            (activedrag.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then
            activedrag=nil
        end
    end))
    track(inputservice.InputBegan:Connect(function(input,processed)
        if input.KeyCode==Enum.KeyCode.Escape then
            if win.Popup then killpopup(win);return end
        end
        if not processed and not library.KeyCapture and not inputservice:GetFocusedTextBox() and
            win.ToggleKey~=Enum.KeyCode.Unknown and input.KeyCode==win.ToggleKey then
            win:setvisible(not win.Visible)
        end
    end))
    function win:setvisible(show,immediate)
        self.Visible=not not show
        self.VisibilityGeneration=(self.VisibilityGeneration or 0)+1
        local generation=self.VisibilityGeneration
        if not self.Visible then killpopup(self) end
        if immediate or not library.Animations then
            root.Visible=self.Visible
            reopen.Visible=not self.Visible
            veil.Visible=false
            return
        end
        if self.Visible then
            reopen.Visible=false
            root.Visible=true
            veil.Visible=true
            veil.BackgroundTransparency=0
            smooth(veil,{BackgroundTransparency=1},.15)
            task.delay(.17,function()
                if generation==self.VisibilityGeneration and veil.Parent then veil.Visible=false end
            end)
        else
            veil.Visible=true
            veil.BackgroundTransparency=1
            smooth(veil,{BackgroundTransparency=0},.15)
            task.delay(.17,function()
                if generation~=self.VisibilityGeneration or library.Destroyed then return end
                root.Visible=false
                reopen.Visible=true
                veil.Visible=false
            end)
        end
    end
    function win:destroy() library:destroy() end
    function win:relayout()
        if library.Destroyed then return end
        local v=viewport()
        local mobile=v.X<850 or (inputservice.TouchEnabled and v.Y<520)
        local landscape=v.X>v.Y*1.3
        self.Mobile=mobile
        local w,h
        if mobile then
            w=math.clamp(math.floor(v.X-16),320,834)
            h=landscape and math.clamp(math.floor(v.Y-16),300,540)
                or math.clamp(math.floor(v.Y-16),430,720)
        else
            w=834
            h=math.min(586,math.max(430,math.floor(v.Y-14)))
        end
        self.Stacked=mobile and w<630
        self.Width=w;self.Height=h
        local fit=math.min((v.X-14)/w,(v.Y-14)/h)
        self.Scale.Scale=math.clamp(math.min(fit,library.UIBaseScale),.2,1.3)
        root.Size=UDim2.fromOffset(w,h)
        if not self.Dragged then
            root.Position=UDim2.fromScale(.5,.5)
        else
            local current=Vector2.new(root.Position.X.Scale*v.X+root.Position.X.Offset,
                root.Position.Y.Scale*v.Y+root.Position.Y.Offset)
            local half=Vector2.new(w*self.Scale.Scale/2,h*self.Scale.Scale/2)
            local lox,hix=math.min(v.X/2,half.X+5),math.max(v.X/2,v.X-half.X-5)
            local loy,hiy=math.min(v.Y/2,half.Y+5),math.max(v.Y/2,v.Y-half.Y-5)
            root.Position=UDim2.fromOffset(math.clamp(current.X,lox,hix),math.clamp(current.Y,loy,hiy))
        end
        top.Size=UDim2.fromOffset(w,55)
        topedge.Size=UDim2.fromOffset(w,1)
        hide.Position=UDim2.fromOffset(w-40,9)
        bottom.Position=UDim2.fromOffset(0,h-(mobile and 64 or 70))
        bottom.Size=UDim2.fromOffset(w,mobile and 64 or 70)
        bottomedge.Position=UDim2.fromOffset(0,h-(mobile and 64 or 70))
        bottomedge.Size=UDim2.fromOffset(w,1)
        if mobile then
            side.Position=UDim2.fromOffset(0,55)
            side.Size=UDim2.fromOffset(w,51)
            divide.Visible=false
            sidelist.Position=UDim2.fromOffset(7,3)
            sidelist.Size=UDim2.fromOffset(w-14,45)
            sidelist.ScrollingDirection=Enum.ScrollingDirection.X
            sidelist.AutomaticCanvasSize=Enum.AutomaticSize.X
            local layout=sidelist:FindFirstChildOfClass("UIListLayout")
            if layout then layout.FillDirection=Enum.FillDirection.Horizontal;layout.Padding=UDim.new(0,3) end
            stage.Position=UDim2.fromOffset(0,106)
            stage.Size=UDim2.fromOffset(w,h-106-64)
            tabstrip.Position=UDim2.fromOffset(5,6)
            tabstrip.Size=UDim2.fromOffset(w-10,53)
        else
            side.Position=UDim2.fromOffset(0,55)
            side.Size=UDim2.fromOffset(167,h-55-70)
            divide.Visible=true
            divide.Position=UDim2.fromOffset(166,55)
            divide.Size=UDim2.fromOffset(1,h-55-70)
            sidelist.Position=UDim2.fromOffset(1,12)
            sidelist.Size=UDim2.fromOffset(165,h-55-70-24)
            sidelist.ScrollingDirection=Enum.ScrollingDirection.Y
            sidelist.AutomaticCanvasSize=Enum.AutomaticSize.Y
            local layout=sidelist:FindFirstChildOfClass("UIListLayout")
            if layout then layout.FillDirection=Enum.FillDirection.Vertical;layout.Padding=UDim.new(0,2) end
            stage.Position=UDim2.fromOffset(167,55)
            stage.Size=UDim2.fromOffset(667,h-55-70)
            tabstrip.Position=UDim2.fromOffset(206,10)
            tabstrip.Size=UDim2.fromOffset(426,51)
        end
        for unused,tab in self.Tabs do
            for unused,page in tab.Pages do
                page:relayout()
                for unused,sub in page.Tabs do sub:relayout() end
            end
        end
        for unused,tab in self.Tabs do
            tab.Slot.Size=UDim2.new(1/math.max(#self.Tabs,1),-1,1,0)
        end
        if self.Popup then self.Popup:destroy() end
    end
    win:relayout()
    track(inputservice:GetPropertyChangedSignal("TouchEnabled"):Connect(function() win:relayout() end))
    local observedcamera=nil
    local cameraconn=nil
    local function hookcamera()
        if cameraconn then cameraconn:Disconnect() end
        observedcamera=workspace.CurrentCamera
        if observedcamera then
            cameraconn=observedcamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                win:relayout()
            end)
            track(cameraconn)
        end
        win:relayout()
    end
    hookcamera()
    track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(hookcamera))
    return win
end

function windowclass:addtab(name,icon)
    local tab=setmetatable({Name=tostring(name),Pages={},Window=self},tabclass)
    local index=#self.Tabs+1
    table.insert(self.Tabs,tab)
    local slot=rect(self.TabStrip,0,0,68,51,theme.Top,6)
    slot.BackgroundTransparency=1
    slot.LayoutOrder=index
    slot.Size=UDim2.new(1/#self.Tabs,-1,1,0)
    local background=rect(slot,0,0,0,0,theme.Top,6)
    background.Size=UDim2.fromScale(1,1)
    background.BackgroundTransparency=1
    round(background,8)
    local iconname=type(icon)=="string" and images[icon] and icon or string.lower(tostring(name))
    local image=nil
    if images[iconname] then
        image=new("ImageLabel",background,{BackgroundTransparency=1,Image=images[iconname],ImageColor3=theme.Muted,
            Position=UDim2.new(.5,-12,0,5),Size=UDim2.fromOffset(24,24),ZIndex=7})
    else
        local shape=rect(background,0,0,19,19,theme.Muted,7)
        shape.AnchorPoint=Vector2.new(.5,0)
        shape.Position=UDim2.new(.5,0,0,7)
        round(shape,8)
        image=shape
    end
    local caption=label(background,name,0,33,0,16,10,theme.Muted,true,Enum.TextXAlignment.Center,7)
    caption.Size=UDim2.new(1,0,0,16)
    local buttonobj=hit(slot,"",0,0,0,0,theme.Top,8)
    buttonobj.Size=UDim2.fromScale(1,1)
    buttonobj.BackgroundTransparency=1
    tab.Slot=slot;tab.Background=background;tab.Image=image;tab.Caption=caption
    function tab:select(refreshonly)
        if not refreshonly then killpopup(self.Window) end
        local win=self.Window
        win.ActiveTab=self
        if not self.ActivePage then self.ActivePage=self.Pages[1] end
        for unused,other in win.Tabs do
            local tabactive=other==self
            if not other.ActivePage then other.ActivePage=other.Pages[1] end
            smooth(other.Background,{BackgroundTransparency=tabactive and 0 or 1,
                BackgroundColor3=rgb(43,43,43)},.12)
            local iconproperty=other.Image:IsA("ImageLabel") and "ImageColor3" or "BackgroundColor3"
            smooth(other.Image,{[iconproperty]=tabactive and theme.Text or theme.Muted},.12)
            smooth(other.Caption,{TextColor3=tabactive and theme.Text or theme.Muted},.12)
            for unused,page in other.Pages do
                local chosen=tabactive and other.ActivePage==page
                page.SideButton.Visible=tabactive
                page.View.Visible=chosen
                page.Bar.Visible=chosen
                smooth(page.SideBg,{BackgroundTransparency=chosen and 0 or 1,
                    BackgroundColor3=rgb(33,33,33)},0)
                page.NameLabel.TextColor3=chosen and theme.Text or theme.Muted
                if chosen and not page.ActiveSubTab then page.ActiveSubTab=page.Tabs[1] end
                for unused,sub in page.Tabs do
                    local activesub=chosen and page.ActiveSubTab==sub
                    sub.Body.Visible=activesub
                    smooth(sub.Button,{TextColor3=activesub and theme.AccentBright or theme.Muted},0)
                end
            end
        end
    end
    buttonobj.MouseEnter:Connect(function() if self.ActiveTab~=tab then smooth(background,{BackgroundColor3=theme.Hover,BackgroundTransparency=.4},.12) end end)
    buttonobj.MouseLeave:Connect(function()
        if self.ActiveTab~=tab then smooth(background,{BackgroundTransparency=1},0) end
    end)
    buttonobj.MouseButton1Click:Connect(function() tab:select() end)
    if index==1 then tab:select() end
    for unused,t in self.Tabs do t.Slot.Size=UDim2.new(1/#self.Tabs,-1,1,0) end
    return tab
end

function tabclass:addpage(name,description)
    local page=setmetatable({Name=name,Description=description or "",Tabs={},Window=self.Window,Tab=self},pageclass)
    table.insert(self.Pages,page)
    local b=hit(self.Window.Sidebar,"",0,0,165,46,theme.Sidebar,5)
    b.LayoutOrder=#self.Pages
    b.BackgroundTransparency=1
    local background=rect(b,0,0,0,0,theme.Sidebar,5)
    background.Size=UDim2.fromScale(1,1)
    background.BackgroundTransparency=1
    local marker=rect(background,1,0,2,46,theme.Accent,6)
    accentobject(marker,"BackgroundColor3")
    local title=label(background,name,9,5,0,17,11,theme.Muted,true)
    title.Size=UDim2.new(1,-12,0,17)
    local hint=label(background,page.Description,9,23,0,14,9,theme.Muted,false)
    hint.Size=UDim2.new(1,-12,0,14)
    local click=hit(b,"",0,0,0,0,theme.Sidebar,8)
    click.Size=UDim2.fromScale(1,1)
    click.BackgroundTransparency=1
    page.SideButton=b;page.SideBg=background;page.Bar=marker;page.NameLabel=title;page.DescLabel=hint
    local view=rect(self.Window.Stage,13,12,640,440,theme.Background,4)
    view.BackgroundTransparency=1
    local segment=rect(view,0,0,640,32,theme.Background,5)
    round(segment,5);border(segment,theme.Border)
    local seglist=rect(segment,1,1,638,30,theme.Background,6)
    seglist.BackgroundTransparency=1
    new("UIListLayout",seglist,{FillDirection=Enum.FillDirection.Horizontal,
        SortOrder=Enum.SortOrder.LayoutOrder,Padding=UDim.new(0,0)})
    page.View=view;page.Segment=seglist;page.SegmentContainer=segment
    function page:relayout()
        local mobile=self.Window.Mobile
        local ww=self.Window.Width
        local h=self.Window.Height
        if mobile then
            b.Size=UDim2.fromOffset(135,44)
            marker.Size=UDim2.fromOffset(2,44)
            title.Position=UDim2.fromOffset(9,0)
            title.Size=UDim2.new(1,-12,1,0)
            title.TextSize=11
            hint.Visible=false
            view.Position=UDim2.fromOffset(8,8)
            view.Size=UDim2.fromOffset(ww-16,h-106-64-16)
        else
            b.Size=UDim2.fromOffset(165,46)
            marker.Size=UDim2.fromOffset(2,46)
            title.Position=UDim2.fromOffset(9,5)
            title.Size=UDim2.new(1,-12,0,17)
            hint.Visible=true
            view.Position=UDim2.fromOffset(13,12)
            view.Size=UDim2.fromOffset(640,h-55-70-24)
        end
        segment.Size=UDim2.new(1,0,0,32)
        seglist.Size=UDim2.new(1,-2,0,30)
        for unused,sub in self.Tabs do
            for unused,div in sub.Dividers or {} do if div.Parent then div:Destroy() end end
            sub.Dividers={}
        end
    end
    function page:select()
        if self.Window.ActiveTab~=self.Tab then self.Tab:select(true) end
        killpopup(self.Window)
        self.Tab.ActivePage=self
        if not self.ActiveSubTab then self.ActiveSubTab=self.Tabs[1] end
        self.Tab:select(true)
    end
    click.MouseButton1Click:Connect(function() page:select() end)
    click.MouseEnter:Connect(function()
        if self.Window.ActiveTab==self and self.ActivePage~=page then
            smooth(background,{BackgroundTransparency=.45,BackgroundColor3=theme.Hover},.09)
        end
    end)
    click.MouseLeave:Connect(function()
        if self.Window.ActiveTab==self and self.ActivePage~=page then
            smooth(background,{BackgroundTransparency=1,BackgroundColor3=theme.Sidebar},0)
        end
    end)
    b.Visible=self.Window.ActiveTab==self
    view.Visible=false
    marker.Visible=false
    page:relayout()
    if not self.ActivePage then self.ActivePage=page end
    if self.Window.ActiveTab==self then self:select(true) end
    return page
end

function pageclass:addsubtab(name)
    local sub=setmetatable({Name=name,Groups={},Window=self.Window,Page=self,Dividers={}},subtabclass)
    table.insert(self.Tabs,sub)
    local count=#self.Tabs
    local segment=hit(self.Segment,name,0,0,0,30,theme.Background,7)
    segment.FontFace=bold
    segment.TextTruncate=Enum.TextTruncate.AtEnd
    segment.TextColor3=theme.Muted
    segment.LayoutOrder=count
    segment.Size=UDim2.new(1/count,0,1,0)
    sub.Button=segment
    for unused,other in self.Tabs do other.Button.Size=UDim2.new(1/count,0,1,0) end
    local body=rect(self.View,0,45,640,385,theme.Background,5)
    body.BackgroundTransparency=1
    sub.Body=body
    sub.Left=scrolling(body,0,0,312,385)
    sub.Right=scrolling(body,326,0,312,385)
    sub.Mobile=scrolling(body,0,0,640,385)
    sub.Mobile.Visible=false
    function sub:relayout()
        local stacked=self.Window.Stacked
        body.Size=UDim2.new(1,0,1,-54)
        self.Left.Visible=not stacked
        self.Right.Visible=not stacked
        self.Mobile.Visible=stacked
        if stacked then
            self.Mobile.Position=UDim2.fromOffset(0,0)
            self.Mobile.Size=UDim2.new(1,0,1,0)
        else
            local vieww=self.Window.Mobile and (self.Window.Width-16) or 640
            local colw=math.floor((vieww-14)/2)
            self.Left.Position=UDim2.fromOffset(0,0)
            self.Left.Size=UDim2.new(0,colw,1,0)
            self.Right.Position=UDim2.fromOffset(colw+14,0)
            self.Right.Size=UDim2.new(0,colw,1,0)
        end
        for unused,g in self.Groups do
            local target=stacked and self.Mobile or (g.Side=="Right" and self.Right or self.Left)
            if g.Container.Parent~=target then g.Container.Parent=target end
            g:refreshheight()
            for unused,control in g.ResponsiveControls do control:relayout() end
        end
    end
    function sub:select()
        killpopup(self.Window)
        self.Page.ActiveSubTab=self
        for unused,other in self.Page.Tabs do
            other.Body.Visible=other==self and self.Page.View.Visible
            smooth(other.Button,{TextColor3=other==self and theme.AccentBright or theme.Muted},0)
        end
    end
    function sub:addgroupbox(title,side,minheight)
        library.CurrentWindow=self.Window
        return creategroup(self,title,side,minheight)
    end
    sub.addgroup=sub.addgroupbox
    segment.MouseButton1Click:Connect(function() sub:select() end)
    segment.MouseEnter:Connect(function()
        if self.ActiveSubTab~=sub then smooth(segment,{TextColor3=theme.Text},.12) end
    end)
    segment.MouseLeave:Connect(function()
        if self.ActiveSubTab~=sub then smooth(segment,{TextColor3=theme.Muted},0) end
    end)
    body.Visible=false
    sub:relayout()
    if count==1 then sub:select() end
    return sub
end

local function validconfigname(value)
    local name=tostring(value or "Default")
    name=name:gsub("%.json$",""):gsub("^%s+",""):gsub("%s+$","")
    name=name:gsub("[^%w_%- ]","_"):sub(1,50)
    if name=="" then name="Default" end
    return name
end
local function configpath(name)
    return library.ConfigFolder.."/"..validconfigname(name)..".json"
end
function library:listconfigs()
    local results={}
    if type(listfiles)~="function" then return results end
    folder(self.ConfigFolder)
    local ok,files=pcall(listfiles,self.ConfigFolder)
    if not ok or type(files)~="table" then return results end
    local used={}
    for unused,fullpath in files do
        local file=tostring(fullpath):gsub("\\","/"):match("([^/]+)%.json$")
        if file and file~="autoload" and not used[file] then
            table.insert(results,file)
            used[file]=true
        end
    end
    table.sort(results,function(a,b) return a:lower()<b:lower() end)
    return results
end
library.getconfigs=library.listconfigs
function library:saveconfig(name)
    if type(writefile)~="function" then return false,"writefile unavailable" end
    folder(self.ConfigFolder)
    local entries={}
    for id,control in self.Options do
        if not control.NoSave and control:getvalue()~=nil then
            local value=control:getvalue()
            if control.Kind=="ColorPicker" then value=hex(value)
            elseif control.Kind=="KeyPicker" then value={Key=keytext(value),Mode=control.Mode} end
            entries[id]={Kind=control.Kind,Value=value}
        end
    end
    local file={Format="PrimordialUI",Version=2,Name=validconfigname(name),Options=entries}
    local ok,err=pcall(function()
        writefile(configpath(name),httpservice:JSONEncode(file))
    end)
    return ok,err
end
function library:loadconfig(name)
    if type(readfile)~="function" then return false,"readfile unavailable" end
    local path=configpath(name)
    local ok,raw=pcall(readfile,path)
    if not ok then return false,raw end
    local parsedok,data=pcall(function() return httpservice:JSONDecode(raw) end)
    if not parsedok or type(data)~="table" then return false,"invalid configuration JSON" end
    local entries=data.Options or data
    if type(entries)~="table" then return false,"invalid configuration entries" end
    local loaded=0
    for id,entry in entries do
        local control=self.Options[id]
        if control and type(entry)=="table" then
            local value=entry.Value
            if value==nil then value=entry.value end
            if value~=nil then
                local applied,result=pcall(function() return control:setvalue(value) end)
                if applied and result~=false then loaded+=1 end
            end
        end
    end
    return true,loaded
end
function library:deleteconfig(name)
    if type(delfile)~="function" then return false,"delfile unavailable" end
    local ok,result=pcall(delfile,configpath(name))
    if ok and self:getautoload()==validconfigname(name) then self:setautoload(nil) end
    return ok,result
end
function library:setautoload(name)
    folder("PrimordialUI")
    local path="PrimordialUI/autoload.json"
    if name==nil or name=="" then
        if type(isfile)=="function" and type(delfile)=="function" then
            local ok,exists=pcall(isfile,path)
            if ok and exists then return pcall(delfile,path) end
        end
        return true
    end
    if type(writefile)~="function" then return false,"writefile unavailable" end
    if type(isfile)=="function" then
        local ok,exists=pcall(isfile,configpath(name))
        if ok and not exists then return false,"save the config first" end
    end
    return pcall(writefile,path,httpservice:JSONEncode({Config=validconfigname(name)}))
end
function library:getautoload()
    if type(readfile)~="function" then return nil end
    local ok,result=pcall(function() return httpservice:JSONDecode(readfile("PrimordialUI/autoload.json")) end)
    return ok and type(result)=="table" and result.Config or nil
end

library.Notifications={}
function library:notify(message,duration,kind)
    if self.Destroyed then return end
    local toastduration=math.clamp(tonumber(duration) or 3.5,1,20)
    local notificationkind=tostring(kind or "info"):lower()
    local title=(notificationkind=="success" and "SUCCESS") or
        (notificationkind=="error" and "ERROR") or (notificationkind=="warning" and "WARNING") or "PRIMORDIAL"
    local themecolor=(notificationkind=="error" and rgb(219,110,120)) or
        (notificationkind=="success" and theme.Green) or theme.Accent
    local cards=self.Notifications
    if #cards>=4 then
        local oldest=cards[1]
        if oldest and oldest.close then oldest:close(true) end
    end
    local holder=rect(screen,0,0,286,67,rgb(28,28,29),90,"Frame")
    holder.AnchorPoint=Vector2.new(1,1)
    holder.Position=UDim2.new(1,300,1,-14)
    round(holder,7)
    border(holder,theme.Border)
    local stripe=rect(holder,0,0,3,67,themecolor,92)
    local icondisc=rect(holder,11,14,25,25,theme.Input,92)
    round(icondisc,13);border(icondisc,theme.Border)
    local infoicon=label(icondisc,notificationkind=="error" and "!" or "i",0,0,25,25,14,themecolor,true,Enum.TextXAlignment.Center,93)
    local heading=label(holder,title,45,7,202,21,10,themecolor,true,nil,93)
    heading.TextTransparency=0
    local body=label(holder,tostring(message),45,27,206,30,11,theme.Text,false,nil,93)
    body.TextWrapped=true
    body.TextYAlignment=Enum.TextYAlignment.Top
    body.TextTruncate=Enum.TextTruncate.AtEnd
    local close=hit(holder,"",257,8,20,20,theme.Input,94)
    close.BackgroundTransparency=1
    local closea=rect(close,5,9,11,2,theme.Muted,95)
    closea.Rotation=45
    local closeb=rect(close,5,9,11,2,theme.Muted,95)
    closeb.Rotation=-45
    local progress=rect(holder,0,64,286,3,themecolor,93)
    local closed=false
    local record={Frame=holder,Close=nil}
    table.insert(cards,record)
    local function reposition(animated)
        local offset=14
        for i=#cards,1,-1 do
            local item=cards[i]
            if item.Frame and item.Frame.Parent then
                local destination=UDim2.new(1,-14,1,-offset)
                smooth(item.Frame,{Position=destination},animated and .16 or 0)
                offset+=75
            end
        end
    end
    function record:close(immediate)
        if closed then return end
        closed=true
        local index=table.find(cards,self)
        if index then table.remove(cards,index) end
        if not holder.Parent then reposition(true);return end
        if immediate or not library.Animations then
            holder:Destroy()
            reposition(true)
            return
        end
        smooth(holder,{Position=UDim2.new(1,300,1,holder.Position.Y.Offset),BackgroundTransparency=1},.18)
        task.delay(.19,function()
            if holder.Parent then holder:Destroy() end
        end)
        reposition(true)
    end
    close.MouseButton1Click:Connect(function() record:close() end)
    holder.MouseEnter:Connect(function()
        smooth(holder,{BackgroundColor3=rgb(38,36,37)},.09)
    end)
    holder.MouseLeave:Connect(function()
        smooth(holder,{BackgroundColor3=rgb(28,28,29)},0)
    end)
    reposition(true)
    if self.Animations then
        local progresstween=tweenservice:Create(progress,TweenInfo.new(toastduration,Enum.EasingStyle.Linear),
            {Size=UDim2.new(0,0,0,3)})
        progresstween:Play()
    end
    task.delay(toastduration,function() record:close() end)
    return record
end

